class Solution:
    def miceAndCheese(self, reward1: list[int], reward2: list[int], k: int) -> int:
        base = sum(reward2)
        diffs = [r1 - r2 for r1, r2 in zip(reward1, reward2)]
        diffs.sort(reverse=True)
        return base + sum(diffs[:k])

class Solution {
public:
    int miceAndCheese(std::vector<int>& reward1, std::vector<int>& reward2, int k) {
        int n = reward1.size();
        int base = 0;
        std::vector<int> diffs(n);
        for (int i = 0; i < n; ++i) {
            base += reward2[i];
            diffs[i] = reward1[i] - reward2[i];
        }
        std::sort(diffs.begin(), diffs.end(), std::greater<int>());
        for (int i = 0; i < k; ++i) {
            base += diffs[i];
        }
        return base;
    }
};

class Solution {
    public int miceAndCheese(int[] reward1, int[] reward2, int k) {
        int n = reward1.length;
        int base = 0;
        Integer[] diffs = new Integer[n];
        for (int i = 0; i < n; i++) {
            base += reward2[i];
            diffs[i] = reward1[i] - reward2[i];
        }
        java.util.Arrays.sort(diffs, java.util.Collections.reverseOrder());
        for (int i = 0; i < k; i++) {
            base += diffs[i];
        }
        return base;
    }
}

